head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[checkcombobox > P > displayAllOptionLabel]<br/>allOption=true 일때 아이템이 모두 선택되면 컴포넌트의 라벨 표시 영역에 '전체 선택' 을 표시할지 설정합니다.",
    "validation" : [
        "미설정 시 선택된 아이템의 Label 값이 separator 속성값으로 구분되어 컴포넌트의 라벨 표시 영역에 표시됩니다.",
        "true 설정 시 모든 아이템이 선택되면 컴포넌트의 라벨 표시 영역에 '전체 선택' 이 표시됩니다.",
        "false 설정 시 선택된 아이템의 Label 값이 separator 속성값으로 구분되어 컴포넌트의 라벨 표시 영역에 표시됩니다.",
        "아이템 리스트에서 일부 아이템만 선택된 경우는 false 로 동작합니다.",
        "실제 컴포넌트의 Value 와 Label 값은 선택된 컴포넌트의 Value 와 Label 값을 separator 속성값으로 구분한 값이 설정됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        allOption : true,
        displayAllOptionLabel : con_displayAllOptionLabel.getText(),
    }

    let cList = $c.gcm.createCList(properties)    

    // comp 생성 함수 호출
    $c.gcm.createBasicCheckComboBox(cList);    
}




scwin.btn_getCompInfo_onclick = function (e) {   
    let rtn = ''

    rtn = target1.render.textContent;
    wf_body_bottom.getObj("scwin").setReturnValue("label : " + rtn);  

    rtn = target1.getText();
    wf_body_bottom.getObj("scwin").setReturnValue("getText : " + rtn);  

    rtn = target1.getValue();
    wf_body_bottom.getObj("scwin").setReturnValue("getValue : " + rtn);  
}
